def greet():
    print("Hi")
greet()

def add(a, b):
    return a + b
print(add(3, 5))

def do_nothing():
    pass
print(do_nothing())

def min_max(values):
    return min(values), max(values)
lo, hi = min_max([3, 9, 1])
print(lo, hi)

def greet(name="Guest"):
    print(f"Hello, {name}!")
greet()

def describe(animal, name):
    print(f"{name} is a {animal}.")
describe(name="Kitty", animal="cat")

def add_numbers(*args):
    return sum(args)
print(add_numbers(1, 2, 3, 4))

def even_only(numbers):
    result = []
    for n in numbers:
        if n % 2 == 0:
            result.append(n)
    return result
print(even_only([1, 2, 3, 4]))

def factorial(n):
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result
print(factorial(5))

def fibonacci(n):
    if n <= 1:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)
print(fibonacci(6))

def clean_email(raw):
    return raw.strip().lower()
print(clean_email("  A@B.COM  "))

def is_admin(role):
    return role.strip().lower() == "admin"
print(is_admin("  Admin  "))

def build_prompt(task, text):
    return f"Task: {task}\nText: {text.strip()}"
print(build_prompt("sum", "  hi  "))

def char_frequency(text):
    freq = {}
    for char in text:
        freq[char] = freq.get(char, 0) + 1
    return freq
print(char_frequency("banana")["a"])

def ready_prompts(prompts):
    ready = []
    for p in prompts:
        clean = p.strip()
        if clean != "":
            ready.append(clean)
    return ready
print(ready_prompts(["  hi  ", "", "go"]))

def average(numbers):
    if len(numbers) == 0:
        return None
    return sum(numbers) / len(numbers)
print(average([2, 4, 6]))

def make_profile(name, age, city="Unknown"):
    return {"name": name, "age": age, "city": city}
print(make_profile("Sam", 20)["city"])

def add(a, b):
    return a + b
print(add(3))

def largest(numbers):
    return max(numbers)
print(largest([4, 9, 1, 7]))

def describe_person(**kwargs):
    return list(kwargs.keys())
print(describe_person(name="Ada", age=36))
